UPDATE public.agent_configuration_catalog SET definition=$catalog${"key": "catalogHistoryRecoveryRules", "target": "policy", "type": "textarea", "label": "Recuperar produto mencionado", "group": "Continuidade e disponibilidade", "description": "Recupera uma única referência no histórico e confirma no catálogo antes de responder. Não executa compra.", "maxLength": 12000, "default": "{\"followup\": \"\\\\b(?:foto|fotos|imagem|imagens|link|esse que.{0,15}sugeriu|desse|dele|dessa|dela)\\\\b\", \"reference\": \"\\\\b((?=[A-Z0-9.\\\\-]*\\\\d)[A-Z][A-Z0-9]+(?:[-.][A-Z0-9]+)*)\\\\b\", \"historyTurns\": 20}"}$catalog$::jsonb,updated_at=now() WHERE key='catalogHistoryRecoveryRules';
